(() => {
 const q=(s,r=document)=>r.querySelector(s),qa=(s,r=document)=>[...r.querySelectorAll(s)];
 const mobile=()=>matchMedia('(max-width:970px)').matches;
 const reduce=()=>matchMedia('(prefers-reduced-motion:reduce)').matches;
 // Retain the original site's text rollover without reading the duplicate label twice.
 const rollSelector='.button,.text-link,.header-phone,.nav-trigger,.nav-plain,.mega-link-name,.mobile-product-cta>a,.product-card h3,.product-more,.mega-more';
 function enhance(scope=document){const els=[...(scope.matches?.(rollSelector)?[scope]:[]),...qa(rollSelector,scope)];els.forEach(el=>{[...el.childNodes].filter(n=>n.nodeType===3&&n.textContent.trim()).forEach(node=>{const label=node.textContent.trim(),window=document.createElement('span');window.className='roll-window';const first=document.createElement('span'),second=document.createElement('span');first.className=second.className='roll-line';first.textContent=second.textContent=label;second.setAttribute('aria-hidden','true');window.append(first,second);node.replaceWith(window);});});}
 enhance();new MutationObserver(records=>{records.forEach(r=>r.addedNodes.forEach(n=>{if(n.nodeType===1)enhance(n);else if(n.nodeType===3&&n.parentElement)enhance(n.parentElement);}));}).observe(document.body,{childList:true,subtree:true});
 // White mega navigation, with the same groups and menu items as the source site.
 const header=q('.header-v4'),items=qa('.nav-item',header);let navTimer,lastHeaderHeight=0;
 function syncHeaderOffset(){const height=Math.round(header.getBoundingClientRect().height);if(height!==lastHeaderHeight){lastHeaderHeight=height;document.documentElement.style.setProperty('--header-offset',height+'px');}}
 function closeItem(item){item.classList.remove('is-expanded');q('.nav-trigger',item).setAttribute('aria-expanded','false');q('.mega-panel',item).hidden=true;}
 function closeMegas(){clearTimeout(navTimer);items.forEach(closeItem);}
 function openItem(item){clearTimeout(navTimer);syncHeaderOffset();items.forEach(other=>{if(other!==item)closeItem(other);});item.classList.add('is-expanded');q('.nav-trigger',item).setAttribute('aria-expanded','true');q('.mega-panel',item).hidden=false;}
 items.forEach(item=>{const trigger=q('.nav-trigger',item);trigger.addEventListener('click',e=>{if(!mobile()&&e.detail>0){openItem(item);return;}item.classList.contains('is-expanded')?closeItem(item):openItem(item);});item.addEventListener('pointerenter',e=>{if(!mobile()&&e.pointerType==='mouse')openItem(item);});item.addEventListener('pointerleave',()=>{if(!mobile())navTimer=setTimeout(()=>closeItem(item),180);});item.addEventListener('focusout',e=>{if(!mobile()&&!item.contains(e.relatedTarget))closeItem(item);});trigger.addEventListener('keydown',e=>{if(e.key==='ArrowDown'){e.preventDefault();openItem(item);q('.mega-panel a',item)?.focus();}});qa('a',item).forEach(a=>a.addEventListener('click',closeMegas));});
 document.addEventListener('click',e=>{if(!e.target.closest('.nav-item'))closeMegas();});document.addEventListener('keydown',e=>{if(e.key==='Escape'){const active=items.find(i=>i.classList.contains('is-expanded'));closeMegas();if(mobile())q('.menu-toggle').focus();else if(active)q('.nav-trigger',active).focus();}});
 q('.menu-toggle').addEventListener('click',()=>{if(!q('#mainNav').classList.contains('is-open'))closeMegas();});qa('.header-actions a[href="#enquire"]').forEach(a=>a.addEventListener('click',()=>{closeMenu();closeMegas();}));
 function updateHeader(){if(document.body.classList.contains('menu-open'))return;const compact=document.body.classList.contains('is-scrolled');const y=Math.max(0,window.scrollY);if(!compact&&y>140)document.body.classList.add('is-scrolled');else if(compact&&y<20)document.body.classList.remove('is-scrolled');}
 window.addEventListener('scroll',updateHeader,{passive:true});updateHeader();syncHeaderOffset();new ResizeObserver(syncHeaderOffset).observe(header);document.fonts?.ready.then(syncHeaderOffset);
 matchMedia('(min-width:971px)').addEventListener('change',()=>{closeMenu();closeMegas();updateHeader();});
 // Source feature explanations, usable on mouse, keyboard and touch.
 let shownTip=null,shownButton=null,tipTimer;
 function hideTip(){clearTimeout(tipTimer);if(shownTip)shownTip.hidden=true;if(shownButton)shownButton.setAttribute('aria-expanded','false');shownTip=shownButton=null;}
 function showTip(button){clearTimeout(tipTimer);const tip=document.getElementById(button.getAttribute('aria-describedby'));if(!tip)return;if(shownButton!==button)hideTip();shownButton=button;shownTip=tip;tip.hidden=false;button.setAttribute('aria-expanded','true');const rect=button.getBoundingClientRect(),box=tip.getBoundingClientRect(),left=Math.max(15,Math.min(rect.left-15,innerWidth-box.width-15));let top=rect.bottom+9;if(top+box.height>innerHeight-15)top=rect.top-box.height-9;tip.style.left=left+'px';tip.style.top=Math.max(12,top)+'px';}
 qa('.feature-info').forEach(button=>{const tip=document.getElementById(button.getAttribute('aria-describedby'));document.body.append(tip);button.addEventListener('pointerenter',e=>{if(e.pointerType==='mouse')showTip(button);});button.addEventListener('pointerleave',()=>{tipTimer=setTimeout(hideTip,130);});button.addEventListener('focus',()=>showTip(button));button.addEventListener('blur',()=>hideTip());button.addEventListener('click',()=>showTip(button));tip.addEventListener('pointerenter',()=>clearTimeout(tipTimer));tip.addEventListener('pointerleave',hideTip);});
 document.addEventListener('click',e=>{if(!e.target.closest('.feature-info,.feature-tooltip'))hideTip();});document.addEventListener('keydown',e=>{if(e.key==='Escape')hideTip();});document.addEventListener('scroll',hideTip,{capture:true,passive:true});
 // Desktop drag and touch swipe supplement the thumbnail, arrow and keyboard controls.
 const gallery=q('#productGallery');
 if(gallery){let drag=null,suppressUntil=0;const total=qa('.gallery-slide',gallery).length;
  gallery.addEventListener('dragstart',e=>e.preventDefault());
  gallery.addEventListener('pointerdown',e=>{if(e.button!==0)return;drag={id:e.pointerId,x:e.clientX,y:e.clientY,left:gallery.scrollLeft,start:performance.now(),moved:false};});
  gallery.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.id)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(!drag.moved){if(Math.abs(dx)<6||Math.abs(dx)<Math.abs(dy))return;drag.moved=true;gallery.classList.add('is-dragging');gallery.setPointerCapture(e.pointerId);}e.preventDefault();gallery.scrollLeft=drag.left-dx;suppressUntil=performance.now()+300;});
  function finish(e){if(!drag||e.pointerId!==drag.id)return;const state=drag;drag=null;gallery.classList.remove('is-dragging');if(gallery.hasPointerCapture(e.pointerId))gallery.releasePointerCapture(e.pointerId);if(!state.moved)return;const dx=e.clientX-state.x,velocity=Math.abs(dx)/Math.max(1,performance.now()-state.start),startIndex=Math.round(state.left/gallery.clientWidth);let index=Math.round(gallery.scrollLeft/gallery.clientWidth);if(Math.abs(dx)>35&&velocity>.35&&index===startIndex)index+=dx<0?1:-1;index=Math.max(0,Math.min(total-1,index));gallery.scrollTo({left:index*gallery.clientWidth,behavior:reduce()?'instant':'smooth'});suppressUntil=performance.now()+300;}
  gallery.addEventListener('pointerup',finish);gallery.addEventListener('pointercancel',e=>{if(drag?.id===e.pointerId){drag=null;gallery.classList.remove('is-dragging');}});gallery.addEventListener('click',e=>{if(performance.now()<suppressUntil){e.preventDefault();e.stopImmediatePropagation();}},true);
 }
 // A compact homepage FAQ list; every source question stays in the document.
 const faqToggle=q('.faq-show-all');if(faqToggle)faqToggle.addEventListener('click',()=>{const expanded=faqToggle.getAttribute('aria-expanded')==='true';qa('[data-extra-faq]').forEach(d=>{d.hidden=expanded;if(expanded)d.open=false;});faqToggle.setAttribute('aria-expanded',String(!expanded));faqToggle.innerHTML=(expanded?'Show all 13 questions':'Show fewer questions')+' <svg class="icon" aria-hidden="true"><use href="#i-'+(expanded?'plus':'close')+'"></use></svg>';if(expanded)q('#faqs').scrollIntoView({behavior:'instant',block:'start'});});
 // Local attachment collection. No upload or enquiry is sent by this design preview.
 const zone=q('#attachmentDropzone'),input=q('#attachmentInput'),list=q('#attachmentList'),status=q('#attachmentStatus');let files=[],previews=[];
 function syncFiles(){const transfer=new DataTransfer();files.forEach(f=>transfer.items.add(f));input.files=transfer.files;previews.forEach(URL.revokeObjectURL);previews=[];list.replaceChildren();files.forEach((file,index)=>{const item=document.createElement('li');if(file.type.startsWith('image/')&&!/heic|heif/i.test(file.type)){const img=document.createElement('img');const url=URL.createObjectURL(file);previews.push(url);img.src=url;img.alt='';img.addEventListener('error',()=>img.remove());item.append(img);}const name=document.createElement('span');name.textContent=file.name+' · '+(file.size/1024/1024<1?Math.max(1,Math.round(file.size/1024))+' KB':(file.size/1024/1024).toFixed(1)+' MB');const remove=document.createElement('button');remove.type='button';remove.setAttribute('aria-label','Remove '+file.name);remove.innerHTML='<svg class="icon" aria-hidden="true"><use href="#i-close"></use></svg>';remove.addEventListener('click',()=>{files.splice(index,1);syncFiles();status.textContent='';});item.append(name,remove);list.append(item);});}
 function addFiles(incoming){const issues=[];for(const file of [...incoming]){if(files.some(f=>f.name===file.name&&f.size===file.size&&f.lastModified===file.lastModified))continue;if(files.length>=5){issues.push('You can attach up to 5 files.');break;}if(file.size>10*1024*1024){issues.push(file.name+' is larger than 10 MB.');continue;}if(!file.type.startsWith('image/')&&file.type!=='application/pdf'&&!/\.(jpe?g|png|webp|gif|heic|heif|avif|pdf)$/i.test(file.name)){issues.push(file.name+': please choose an image or PDF.');continue;}files.push(file);}syncFiles();status.textContent=issues.join(' ');}
 zone.addEventListener('click',()=>input.click());zone.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();input.click();}});input.addEventListener('change',()=>addFiles(input.files));zone.addEventListener('dragover',e=>{e.preventDefault();zone.classList.add('is-dragover');});zone.addEventListener('dragleave',()=>zone.classList.remove('is-dragover'));zone.addEventListener('drop',e=>{e.preventDefault();zone.classList.remove('is-dragover');addFiles(e.dataTransfer.files);});zone.addEventListener('paste',e=>{const pasted=[...e.clipboardData.items].filter(item=>item.kind==='file').map(item=>item.getAsFile()).filter(Boolean);if(pasted.length){e.preventDefault();addFiles(pasted);}});
 window.addEventListener('pagehide',()=>previews.forEach(URL.revokeObjectURL));
})();
